  'tip.minBase': { en: `Traitement`, nl: `Traitement`, fr: `Traitement` },
  'tip.minRes': { en: `Residence allowance (3%)`, nl: `Standplaatstoelage (3%)`, fr: `Indemnité de résidence (3%)` },
  'tip.minFn': { en: `Function allowance (25%)`, nl: `Functietoelage (25%)`, fr: `Indemnité de fonction (25%)` },
  'tip.stateCost': {
    en: `Taxable pay + what the State pays for their pension. No unemployment insurance (it is not a job contract) and nothing for health. This is everything the post costs, and the tax rates on the page are compared to it.`,
    nl: `Belastbaar loon + wat de staat voor hun pensioen betaalt. Geen werkloosheidsverzekering (het is geen arbeidscontract) en niets voor ziekte. Dit is alles wat de functie kost, en de belastingtarieven op de pagina worden ermee vergeleken.`,
    fr: `Rémunération imposable + ce que l'État paie pour leur retraite. Pas d'assurance chômage (ce n'est pas un contrat de travail) et rien pour la maladie. C'est tout ce que coûte la fonction, et les taux de la page sont comparés à ce montant.`,
  },
  'tip.minEr': {
    en: `The State pays the employer part of the general pension (8.55% up to the social security ceiling + 2.11%) and of IRCANTEC (4.20% / 12.55%), on base pay + residence allowance. The ceiling is a yearly pay limit; some contributions stop above it.`,
    nl: `De staat betaalt het werkgeversdeel van het algemene pensioen (8,55% tot het plafond van de sociale zekerheid + 2,11%) en van IRCANTEC (4,20% / 12,55%), op basisloon + standplaatstoelage. Het plafond is een jaarlijkse loongrens; sommige bijdragen stoppen erboven.`,
    fr: `L'État paie la part employeur de la retraite de base (8,55% jusqu'au plafond de la sécurité sociale + 2,11%) et de l'IRCANTEC (4,20% / 12,55%), sur traitement + résidence. Le plafond est une limite annuelle de salaire ; certaines cotisations s'arrêtent au-dessus.`,
  },
  'tip.minEe': {
    en: `General pension: 6.90% up to the ceiling + 0.40%. IRCANTEC: 2.80% up to the ceiling and 6.95% above it. Taken on base pay + residence allowance. Nothing for unemployment.`,
    nl: `Algemeen pensioen: 6,90% tot het plafond + 0,40%. IRCANTEC: 2,80% tot het plafond en 6,95% erboven. Berekend op basisloon + standplaatstoelage. Niets voor werkloosheid.`,
    fr: `Retraite de base : 6,90% jusqu'au plafond + 0,40%. IRCANTEC : 2,80% jusqu'au plafond et 6,95% au-dessus. Pris sur traitement + résidence. Rien pour le chômage.`,
  },
  'tip.minPa': { en: `Not paid at this level of income.`, nl: `Niet uitbetaald bij dit inkomen.`, fr: `Pas versée à ce niveau de revenu.` },

