  trapTitle: { en: (a, b) => `Why so high between ${a} and ${b}?`, nl: (a, b) => `Waarom zo hoog tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi si élevé entre ${a} et ${b} ?` },
  trapBody: {
    en: (a, b, pa, cliff) => `Two kinds of help for low pay shrink as your pay goes up. Your employer gets a discount on its contributions (the RGDU): at the minimum wage (SMIC) it removes contributions worth up to 40% of the salary, and it fades out by 3 times the SMIC. So each extra euro also makes your employer lose part of that discount.${pa ? ` The prime d'activité (a top-up the CAF pays to low earners) drops by about 40 cents for each extra net euro once the flat amount is covered, and stops at ${pa}.` : ''} At ${b} the last 2% of the employer discount disappears all at once: one more euro of gross pay then costs your employer about ${cliff} more a year. Above that, rates go back to the normal contributions and taxes.`,
    nl: (a, b, pa, cliff) => `Twee soorten steun voor lage lonen krimpen als je loon stijgt. Je werkgever krijgt een korting op zijn bijdragen (de RGDU): op het minimumloon (SMIC) schrapt die bijdragen ter waarde van tot 40% van het loon, en ze verdwijnt tegen 3 keer het SMIC. Elke extra euro laat je werkgever dus ook een stuk van die korting verliezen.${pa ? ` De prime d'activité (een aanvulling die de CAF aan lage lonen betaalt) daalt met ongeveer 40 cent per extra netto euro zodra het vaste bedrag gedekt is, en stopt bij ${pa}.` : ''} Bij ${b} valt de laatste 2% van de werkgeverskorting in één keer weg: één euro brutoloon meer kost je werkgever dan ongeveer ${cliff} extra per jaar. Daarboven gelden weer de gewone bijdragen en belastingen.`,
    fr: (a, b, pa, cliff) => `Deux aides aux bas salaires diminuent quand votre salaire monte. Votre employeur a une réduction sur ses cotisations (la RGDU) : au SMIC, elle efface des cotisations qui valent jusqu'à 40% du salaire, et elle disparaît à 3 SMIC. Chaque euro en plus fait donc aussi perdre à votre employeur une partie de cette réduction.${pa ? ` La prime d'activité (un complément versé par la CAF aux petits salaires) baisse d'environ 40 centimes par euro net en plus une fois le forfait couvert, et s'arrête à ${pa}.` : ''} À ${b}, les derniers 2% de la réduction disparaissent d'un coup : un euro brut de plus coûte alors environ ${cliff} de plus par an à votre employeur. Au-delà, on revient aux cotisations et impôts normaux.`,
  },
  topTitle: {
    en: (top, cehr) => `Why the step at ${top}${cehr ? ` and again at ${cehr}` : ''}?`,
    nl: (top, cehr) => `Waarom de sprong bij ${top}${cehr ? ` en opnieuw bij ${cehr}` : ''}?`,
    fr: (top, cehr) => `Pourquoi la marche à ${top}${cehr ? ` et encore à ${cehr}` : ''} ?`,
  },
  topBody: {
    en: (top, cehr, br, parts) => `From ${top}, your household's taxable income divided by its ${parts} parts goes above ${br}. Every euro above that is taxed at the highest rate, 45%.${cehr ? ` At ${cehr} an extra tax on high incomes (CEHR) adds 3%, then 4% higher up.` : ''}`,
    nl: (top, cehr, br, parts) => `Vanaf ${top} komt het belastbaar inkomen van je gezin, gedeeld door zijn ${parts} delen, boven ${br}. Elke euro daarboven wordt belast aan het hoogste tarief, 45%.${cehr ? ` Bij ${cehr} komt er een extra belasting op hoge inkomens (CEHR) bij: 3%, verderop 4%.` : ''}`,
    fr: (top, cehr, br, parts) => `À partir de ${top}, le revenu imposable de votre foyer divisé par ses ${parts} parts dépasse ${br}. Chaque euro au-dessus est imposé au taux le plus haut, 45%.${cehr ? ` À ${cehr}, une taxe en plus sur les hauts revenus (CEHR) ajoute 3%, puis 4% plus haut.` : ''}`,
  },

